const CATEGORIAS = 'Comida (menú, restaurantes, snacks, delivery, supermercado), Transporte (taxi, Uber, InDrive, bus, combustible, peaje), Ocio (cine, salidas, juegos, bebidas, conciertos, streaming), Compras (ropa, tecnología, tiendas, artículos personales), Salud (farmacia, clínica, gimnasio), Educación (cursos, libros, universidad), Servicios (celular, internet, luz, agua, suscripciones de software), Hogar (casa, limpieza, muebles, ferretería), Otros';
const hoy = $now.setZone('America/Lima').toFormat('yyyy-MM-dd');

return $input.all().map((it, i) => {
  const e = it.json;
  const texto = String(e.text || e.textAsHtml || e.snippet || '')
    .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000);
  const de = (e.from && (e.from.text || (e.from.value && e.from.value[0] && e.from.value[0].address))) || '';
  const prompt = `Eres el lector de notificaciones bancarias de un bot de finanzas personales en Perú. Hoy es ${hoy}.
Analiza este correo y responde SOLO un JSON con esta forma:
{"es_consumo": boolean, "monto": number|null, "moneda": "PEN"|"USD"|null, "comercio": string|null, "fecha": "YYYY-MM-DD"|null, "hora": "HH:MM"|null, "categoria": string, "descripcion": string|null}
Reglas:
- es_consumo=true SOLO si el correo avisa de dinero que SALIÓ de la cuenta o tarjeta del titular: compra o consumo con tarjeta, pago de servicio, yapeo/plin enviado, transferencia enviada, retiro.
- es_consumo=false para: dinero recibido, publicidad, promociones, estados de cuenta, códigos de verificación, alertas de inicio de sesión, operaciones rechazadas o anuladas.
- monto: el importe con punto decimal. moneda: "PEN" para soles (S/), "USD" para dólares (US$ o $).
- comercio: nombre del comercio o persona a la que se pagó, tal como aparece.
- fecha y hora de la operación (24h), si aparecen.
- descripcion: muy corta y en minúsculas, basada en el comercio (ej: "plaza vea", "uber", "pago de luz").
- categoria: exactamente una de: ${CATEGORIAS}.

De: ${de}
Asunto: ${e.subject || ''}
Correo: """${texto}"""`;
  return {
    json: {
      body: {
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        generationConfig: { temperature: 0, responseMimeType: 'application/json' }
      }
    },
    pairedItem: i,
  };
});

// ⚙️ Tu chat_id de Telegram
const CHAT_ID = 'TU_CHAT_ID';
const chat = Number(CHAT_ID);
const CATS = ['Comida', 'Transporte', 'Ocio', 'Compras', 'Salud', 'Educación', 'Servicios', 'Hogar', 'Otros'];
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const q = v => (v === null || v === undefined || v === '') ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const TZ = "'America/Lima'";
const INI_MES = `(date_trunc('month', now() AT TIME ZONE ${TZ}) AT TIME ZONE ${TZ})`;

const out = [];
$input.all().forEach((it, i) => {
  const r = it.json;
  const mail = $('Gmail Trigger').itemMatching(i).json;

  let data = null;
  try {
    const txt = r.candidates[0].content.parts.map(p => p.text || '').join('');
    data = JSON.parse(txt.replace(/```json|```/g, '').trim());
    if (Array.isArray(data)) data = data[0];
  } catch (e) { data = null; }
  if (!data || !data.es_consumo || !(Number(data.monto) > 0)) return;   // no es un gasto → se ignora

  const monto = Math.round(Number(data.monto) * 100) / 100;
  const cat = CATS.find(c => norm(c) === norm(data.categoria)) || 'Otros';
  const comercio = data.comercio ? String(data.comercio).trim().slice(0, 120) : null;
  let desc = data.descripcion ? String(data.descripcion).trim().toLowerCase().slice(0, 190) : (comercio ? comercio.toLowerCase() : null);
  if (String(data.moneda || '').toUpperCase() === 'USD') desc = (desc ? desc + ' ' : '') + '(USD)';

  // Fecha: la del correo o la de la operación si viene en el texto
  let fechaExpr = 'now()';
  const fMail = mail.date ? DateTime.fromJSDate(new Date(mail.date)) : null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(data.fecha || '')) {
    const hora = /^\d{2}:\d{2}$/.test(data.hora || '') ? data.hora : '12:00';
    const f = DateTime.fromISO(`${data.fecha}T${hora}`, { zone: 'America/Lima' });
    const dias = f.isValid ? $now.diff(f, 'days').days : 999;
    if (dias >= -1 && dias <= 30) fechaExpr = `(${q(data.fecha + ' ' + hora)}::timestamp AT TIME ZONE 'America/Lima')`;
  } else if (fMail && fMail.isValid) {
    fechaExpr = `${q(fMail.toISO())}::timestamptz`;
  }

  const sql = `
WITH nuevo AS (
  SELECT ${fechaExpr}::timestamptz AS fecha, ${monto}::numeric AS monto, ${q(desc)}::text AS descripcion,
         ${q(cat)}::text AS categoria, 'correo'::text AS metodo, ${q(comercio)}::text AS destinatario,
         ${chat}::bigint AS chat_id, ${q(String(mail.subject || '').slice(0, 300))}::text AS mensaje_original,
         ${q(mail.id)}::text AS email_id
), ins AS (
  INSERT INTO gastos (fecha, monto, descripcion, categoria, metodo, destinatario, chat_id, mensaje_original, email_id)
  SELECT n.* FROM nuevo n
  WHERE NOT EXISTS (   -- ya lo registraste a mano o por captura (mismo monto, ±20 min)
    SELECT 1 FROM gastos g
    WHERE g.chat_id = n.chat_id AND g.monto = n.monto
      AND g.fecha BETWEEN n.fecha - interval '20 minutes' AND n.fecha + interval '20 minutes')
  ON CONFLICT (email_id) DO NOTHING
  RETURNING *
)
SELECT (SELECT count(*) FROM ins)::int AS insertado,
       n.chat_id, n.monto, n.descripcion, n.categoria, n.destinatario,
       to_char(n.fecha AT TIME ZONE ${TZ}, 'DD/MM HH24:MI') AS fecha_local,
       (SELECT COALESCE(sum(monto), 0) FROM gastos WHERE chat_id = n.chat_id AND fecha >= ${INI_MES})
         + (SELECT COALESCE(sum(monto), 0) FROM ins WHERE fecha >= ${INI_MES}) AS total_mes,
       (SELECT monto FROM presupuestos WHERE chat_id = n.chat_id AND categoria = n.categoria) AS presupuesto,
       (SELECT COALESCE(sum(monto), 0) FROM gastos WHERE chat_id = n.chat_id AND categoria = n.categoria AND fecha >= ${INI_MES})
         + (SELECT COALESCE(sum(monto), 0) FROM ins WHERE fecha >= ${INI_MES}) AS gastado_cat_mes
FROM nuevo n;`;
  out.push({ json: { sql }, pairedItem: i });
});
return out;

const S = n => 'S/ ' + Number(n || 0).toFixed(2);
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const EMOJI = { 'Comida': '🍔', 'Transporte': '🚕', 'Ocio': '🎮', 'Compras': '🛍️', 'Salud': '💊', 'Educación': '📚', 'Servicios': '💡', 'Hogar': '🏠', 'Otros': '📦' };

const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (!Number(r.insertado)) continue;   // duplicado → no avisa
  const L = [
    '🏦 <b>Gasto detectado en tu correo</b>',
    `💸 <b>${S(r.monto)}</b>${r.descripcion ? ' — ' + esc(r.descripcion) : ''}`,
    `${EMOJI[r.categoria] || '📦'} ${esc(r.categoria)} · 🕒 ${r.fecha_local}`,
    '',
    `Este mes: <b>${S(r.total_mes)}</b>`,
  ];
  if (r.presupuesto !== null && r.presupuesto !== undefined && Number(r.presupuesto) > 0) {
    const p = Number(r.presupuesto), g = Number(r.gastado_cat_mes), pct = g / p * 100;
    if (pct >= 100) L.push('', `🚨 <b>Te pasaste</b> del presupuesto de ${esc(r.categoria)}: ${S(g)} de ${S(p)} (${pct.toFixed(0)}%)`);
    else if (pct >= 80) L.push('', `⚠️ Llevas el ${pct.toFixed(0)}% del presupuesto de ${esc(r.categoria)}. Te quedan ${S(p - g)}.`);
    else L.push(`🎯 ${esc(r.categoria)}: ${S(g)} de ${S(p)} (${pct.toFixed(0)}%)`);
  }
  L.push('', '<i>¿Mal categorizado? /cat comida · ¿No era un gasto? /borrar</i>');
  out.push({ json: { chat_id: r.chat_id, texto: L.join('\n') } });
}
return out;
